// App.js
import React from 'react';
import ReactDOM from 'react-dom';
import { CodeSnippet } from 'carbon-components-react';
import 'carbon-components/css/carbon-components.min.css';

function App() {
  // a single unbroken long string (CRN)
  const longCRN = 'crn:v1:staging:public:secrets-manager:us-south:a/e8775507941f72319a655b1c42f7e';

  return (
    <div style={{ padding: '2rem' }}>
      <h2>Multi‐line CodeSnippet with a single long string</h2>
      <div style={{ width: '400px', border: '1px solid #ddd' }}>
        {/* type="multi" does not wrap the longCRN, shows horizontal scroll */}
        <CodeSnippet type="multi">
          {longCRN}
        </CodeSnippet>
      </div>
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
